-- Base SQL gerada a partir do schema Drizzle existente. Apenas CREATE IF NOT EXISTS e relações NOT VALID.
CREATE TABLE IF NOT EXISTS public."config" ("id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL UNIQUE,"nome_clinica" text NOT NULL DEFAULT 'Laboratório de Análises Clínicas',"nif" text NOT NULL DEFAULT '',"endereco" text NOT NULL DEFAULT 'Luanda, Angola',"telefone" text NOT NULL DEFAULT '',"email" text NOT NULL DEFAULT '',"director_tecnico" text NOT NULL DEFAULT '',"logo_data" text NOT NULL DEFAULT '',"assinatura_data" text NOT NULL DEFAULT '',"serie" text NOT NULL DEFAULT 'A',"proximo_numero_fatura" integer NOT NULL DEFAULT 1,"iva_taxa" numeric NOT NULL DEFAULT '14',"moeda" text NOT NULL DEFAULT 'AOA',"website" text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS public."empresas" ("id" uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),"nome" text NOT NULL,"nif" text NOT NULL DEFAULT '',"username" text NOT NULL UNIQUE,"password" text NOT NULL,"ativo" boolean NOT NULL DEFAULT true,"modulos" jsonb NOT NULL DEFAULT '["laboratorial"]'::jsonb,"parent_empresa_id" uuid);
CREATE TABLE IF NOT EXISTS public."exames_custom" ("id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL,"categoria" text NOT NULL DEFAULT '',"nome" text NOT NULL DEFAULT '',"parametros" jsonb NOT NULL DEFAULT '[]'::jsonb);
CREATE TABLE IF NOT EXISTS public."faturas" ("emitente_snapshot" jsonb,"id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL,"numero" text NOT NULL DEFAULT '',"serie" text NOT NULL DEFAULT 'A',"data" text NOT NULL DEFAULT '',"hora_operacao" text NOT NULL DEFAULT '',"data_vencimento" text NOT NULL DEFAULT '',"cliente_nome" text NOT NULL DEFAULT '',"cliente_nif" text NOT NULL DEFAULT '',"cliente_endereco" text NOT NULL DEFAULT '',"linhas" jsonb NOT NULL DEFAULT '[]'::jsonb,"subtotal_sem_iva" numeric NOT NULL DEFAULT '0',"total_iva" numeric NOT NULL DEFAULT '0',"iva_taxa" numeric NOT NULL DEFAULT '14',"total" numeric NOT NULL DEFAULT '0',"estado" text NOT NULL DEFAULT 'emitida',"observacoes" text NOT NULL DEFAULT '',"paciente_id" integer,"resultado_id" integer,"emitido_por" text NOT NULL DEFAULT '',"codigo_hash" text NOT NULL DEFAULT '',"emissao_contagem" integer NOT NULL DEFAULT 1,"factura_premiada" boolean NOT NULL DEFAULT false,"nota_credito_motivo" text NOT NULL DEFAULT '',"tipo_documento" text NOT NULL DEFAULT 'factura',"forma_pagamento" text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS public."funcionarios" ("id" uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),"empresa_id" uuid NOT NULL,"nome" text NOT NULL,"username" text NOT NULL UNIQUE,"password" text NOT NULL,"funcao" text NOT NULL DEFAULT 'tecnico',"ativo" boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS public."movimentos" ("id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL,"data" text NOT NULL DEFAULT '',"descricao" text NOT NULL DEFAULT '',"tipo" text NOT NULL DEFAULT 'entrada',"valor" numeric NOT NULL DEFAULT '0',"categoria" text NOT NULL DEFAULT '',"fatura_id" integer,"referencia" text NOT NULL DEFAULT '',"registado_por" text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS public."pacientes" ("id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL,"nome" text NOT NULL DEFAULT '',"nasc" text NOT NULL DEFAULT '',"sexo" text NOT NULL DEFAULT '',"idade" text NOT NULL DEFAULT '',"passaporte" text NOT NULL DEFAULT '',"observacoes" text NOT NULL DEFAULT '',"bi" text NOT NULL DEFAULT '',"nif" text NOT NULL DEFAULT '',"nacionalidade" text NOT NULL DEFAULT '',"estado_civil" text NOT NULL DEFAULT '',"profissao" text NOT NULL DEFAULT '',"telefone" text NOT NULL DEFAULT '',"telefone2" text NOT NULL DEFAULT '',"email" text NOT NULL DEFAULT '',"endereco" text NOT NULL DEFAULT '',"grupo_sanguineo" text NOT NULL DEFAULT '',"fator_rh" text NOT NULL DEFAULT '',"alergias" text NOT NULL DEFAULT '',"patologias_cronicas" text NOT NULL DEFAULT '',"medicacao_habitual" text NOT NULL DEFAULT '',"contacto_emergencia_nome" text NOT NULL DEFAULT '',"contacto_emergencia_tel" text NOT NULL DEFAULT '',"empresa" text NOT NULL DEFAULT '',"processo" text NOT NULL DEFAULT '',"medico" text NOT NULL DEFAULT '',"n_amostra" text NOT NULL DEFAULT '',"recolha" text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS public."parceiros_pacientes" ("id" uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),"parceiro_id" uuid NOT NULL,"empresa_id" uuid NOT NULL,"codigo" text NOT NULL DEFAULT '',"nome" text NOT NULL DEFAULT '',"nascimento" text NOT NULL DEFAULT '',"sexo" text NOT NULL DEFAULT '',"telefone" text NOT NULL DEFAULT '',"bi" text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS public."parceiros" ("id" uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),"empresa_id" uuid NOT NULL,"nome" text NOT NULL,"instituicao" text NOT NULL DEFAULT '',"username" text NOT NULL UNIQUE,"password" text NOT NULL,"email" text NOT NULL DEFAULT '',"telefone" text NOT NULL DEFAULT '',"ativo" boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS public."produtos" ("id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL,"stock" numeric NOT NULL DEFAULT '0',"stock_minimo" numeric NOT NULL DEFAULT '0',"codigo" text NOT NULL DEFAULT '',"nome" text NOT NULL DEFAULT '',"categoria" text NOT NULL DEFAULT '',"preco" numeric NOT NULL DEFAULT '0',"iva_isento" boolean NOT NULL DEFAULT false,"descricao" text NOT NULL DEFAULT '',"ativo" boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS public."reagentes" ("id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL,"codigo" text NOT NULL DEFAULT '',"nome" text NOT NULL,"categoria" text NOT NULL DEFAULT '',"tipo" text NOT NULL DEFAULT 'reagente',"unidade" text NOT NULL DEFAULT 'unidades',"quantidade_atual" numeric NOT NULL DEFAULT '0',"quantidade_minima" numeric NOT NULL DEFAULT '0',"lote" text NOT NULL DEFAULT '',"validade" text NOT NULL DEFAULT '',"fornecedor" text NOT NULL DEFAULT '',"localizacao" text NOT NULL DEFAULT '',"observacoes" text NOT NULL DEFAULT '',"ativo" boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS public."resultados" ("id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL,"paciente_id" integer,"paciente_nome" text NOT NULL DEFAULT '',"data" text NOT NULL DEFAULT '',"data_emissao" text NOT NULL DEFAULT '',"parametros" jsonb NOT NULL DEFAULT '[]'::jsonb,"tecnico_nome" text NOT NULL DEFAULT '',"solicitacao_id" text);
CREATE TABLE IF NOT EXISTS public."solicitacoes" ("id" uuid PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),"empresa_id" uuid NOT NULL,"parceiro_id" uuid,"paciente_nome" text NOT NULL DEFAULT '',"paciente_nascimento" text NOT NULL DEFAULT '',"paciente_sexo" text NOT NULL DEFAULT '',"paciente_telefone" text NOT NULL DEFAULT '',"paciente_bi" text NOT NULL DEFAULT '',"exames_solicitados" jsonb NOT NULL DEFAULT '[]'::jsonb,"observacoes" text NOT NULL DEFAULT '',"urgente" boolean NOT NULL DEFAULT false,"estado" text NOT NULL DEFAULT 'pendente',"data" text NOT NULL DEFAULT '',"hora" text NOT NULL DEFAULT '',"resultado_id" text,"medico_solicitante" text NOT NULL DEFAULT '',"tipo_pedido" text NOT NULL DEFAULT 'externo');
CREATE TABLE IF NOT EXISTS public."stock_movimentos" ("id" serial PRIMARY KEY NOT NULL,"empresa_id" uuid NOT NULL,"reagente_id" integer NOT NULL,"tipo" text NOT NULL,"quantidade" numeric NOT NULL DEFAULT '0',"lote" text NOT NULL DEFAULT '',"validade" text NOT NULL DEFAULT '',"motivo" text NOT NULL DEFAULT '',"data" text NOT NULL DEFAULT '',"registado_por" text NOT NULL DEFAULT '');
